#!/usr/bin/env python3
"""Generate the HTML competitive analysis report from pre-computed KPIs."""

import json
import math

with open('/app/kpi_results.json') as f:
    d = json.load(f)

APPS = d['apps_order']
APP_COLORS = {
    'ChatGPT':           '#10A37F',
    'Microsoft Copilot': '#0078D4',
    'Google Gemini':     '#DB4437',
    'Perplexity':        '#5C6BC0',
    'Claude':            '#D4873B',
}
THEME_COLORS = {
    'General':               '#94A3B8',
    'Pricing/Subscription':  '#F59E0B',
    'Bugs/Performance':      '#EF4444',
    'Accuracy/Logic Issues': '#8B5CF6',
}

def pct_bar(value, max_val=100, color='#10A37F', height=18, width=220):
    """Return an SVG horizontal bar."""
    fill = max(0, min(value / max_val, 1)) * width
    return (
        f'<svg width="{width}" height="{height}" style="vertical-align:middle">'
        f'<rect width="{width}" height="{height}" rx="3" fill="#E2E8F0"/>'
        f'<rect width="{fill:.1f}" height="{height}" rx="3" fill="{color}"/>'
        f'</svg>'
    )

def stars_svg(rating, color='#F59E0B'):
    """Return SVG stars for a rating."""
    full = int(rating)
    frac = rating - full
    svgs = []
    cx = 0
    for i in range(5):
        if i < full:
            svgs.append(f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="{color}"/>')
        elif i == full and frac >= 0.3:
            # half star clip
            svgs.append(
                f'<defs><clipPath id="h{i}"><rect x="{cx}" y="0" width="10" height="20"/></clipPath></defs>'
                f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="#E2E8F0"/>'
                f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="{color}" clip-path="url(#h{i})"/>'
            )
        else:
            svgs.append(f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="#E2E8F0"/>')
        cx += 22
    return f'<svg width="{cx}" height="20" style="vertical-align:middle">{"".join(svgs)}</svg>'

# ─── Build chart data for Chart.js ─────────────────────────────────────────────
app_labels = json.dumps(APPS)
bg_colors   = json.dumps([APP_COLORS[a] for a in APPS])
star_vals   = json.dumps([round(d['avg_star'][a], 3) for a in APPS])
pol_vals    = json.dumps([round(d['avg_polarity'][a], 4) for a in APPS])
mis_vals    = json.dumps([round(d['mismatch_rate'][a], 2) for a in APPS])
thumb_vals  = json.dumps([round(d['avg_thumbs'][a], 3) for a in APPS])
words_vals  = json.dumps([round(d['avg_words'][a], 1) for a in APPS])

THEMES = ['General', 'Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']
theme_datasets = []
for theme in THEMES:
    vals = [round(d['theme_pct'].get(a, {}).get(theme, 0), 2) for a in APPS]
    theme_datasets.append({
        'label': theme,
        'data': vals,
        'backgroundColor': THEME_COLORS[theme],
    })
theme_datasets_json = json.dumps(theme_datasets)

# Star distribution stacked bar
STAR_COLORS = {1: '#EF4444', 2: '#F97316', 3: '#EAB308', 4: '#84CC16', 5: '#22C55E'}
star_datasets = []
for star in [1, 2, 3, 4, 5]:
    vals = [round(d['star_dist_pct'].get(a, {}).get(star, 0), 2) for a in APPS]
    star_datasets.append({'label': f'{star}★', 'data': vals, 'backgroundColor': STAR_COLORS[star]})
star_datasets_json = json.dumps(star_datasets)

# Polarity buckets grouped bar
POL_BUCKETS = ['Very Neg', 'Neg', 'Neutral', 'Pos', 'Very Pos']
POL_COLORS  = ['#EF4444', '#F97316', '#94A3B8', '#84CC16', '#22C55E']
pol_datasets = []
for bucket, color in zip(POL_BUCKETS, POL_COLORS):
    vals = [round(d['pol_dist_pct'].get(a, {}).get(bucket, 0), 2) for a in APPS]
    pol_datasets.append({'label': bucket, 'data': vals, 'backgroundColor': color})
pol_datasets_json = json.dumps(pol_datasets)

# Theme thumbs-up
theme_thumb_labels = json.dumps(list(d['theme_thumbs'].keys()))
theme_thumb_vals   = json.dumps([round(v, 3) for v in d['theme_thumbs'].values()])
theme_thumb_colors = json.dumps([THEME_COLORS.get(t, '#94A3B8') for t in d['theme_thumbs'].keys()])

# Words by star
words_by_star_labels = json.dumps([f'{s}★' for s in d['words_by_star'].keys()])
words_by_star_vals   = json.dumps([round(v, 1) for v in d['words_by_star'].values()])
words_by_star_colors = json.dumps([STAR_COLORS[s] for s in [int(k) for k in d['words_by_star'].keys()]])

# ─── KPI cards data ─────────────────────────────────────────────────────────────
best_star_app = max(APPS, key=lambda a: d['avg_star'][a])
worst_star_app = min(APPS, key=lambda a: d['avg_star'][a])
best_pol_app  = max(APPS, key=lambda a: d['avg_polarity'][a])
most_pricing  = max(APPS, key=lambda a: d['theme_pct'].get(a, {}).get('Pricing/Subscription', 0))
most_bugs     = max(APPS, key=lambda a: d['theme_pct'].get(a, {}).get('Bugs/Performance', 0))
most_accuracy = max(APPS, key=lambda a: d['theme_pct'].get(a, {}).get('Accuracy/Logic Issues', 0))
most_mismatch = max(APPS, key=lambda a: d['mismatch_rate'][a])
least_mismatch = min(APPS, key=lambda a: d['mismatch_rate'][a])
most_thumbs   = max(APPS, key=lambda a: d['avg_thumbs'][a])

# ─── HTML Template ──────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Generative AI Competitive Landscape Q1 2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.2/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0F172A;
    --surface: #1E293B;
    --surface2: #273447;
    --border: #334155;
    --text: #F1F5F9;
    --muted: #94A3B8;
    --accent: #38BDF8;
    --chatgpt: {APP_COLORS['ChatGPT']};
    --copilot: {APP_COLORS['Microsoft Copilot']};
    --gemini:  {APP_COLORS['Google Gemini']};
    --perplexity: {APP_COLORS['Perplexity']};
    --claude:  {APP_COLORS['Claude']};
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ background: var(--bg); color: var(--text); font-family: 'Segoe UI', system-ui, sans-serif; font-size: 14px; line-height: 1.6; }}
  a {{ color: var(--accent); }}

  /* ── Layout ── */
  .wrapper {{ max-width: 1200px; margin: 0 auto; padding: 32px 24px; }}
  .page-header {{ border-bottom: 2px solid var(--border); padding-bottom: 24px; margin-bottom: 36px; }}
  .page-header h1 {{ font-size: 26px; font-weight: 700; color: var(--text); line-height: 1.3; }}
  .page-header .subtitle {{ color: var(--muted); font-size: 13px; margin-top: 6px; }}
  .page-header .meta {{ display: flex; gap: 24px; margin-top: 12px; flex-wrap: wrap; }}
  .meta-chip {{ background: var(--surface); border: 1px solid var(--border); border-radius: 20px; padding: 4px 14px; font-size: 12px; color: var(--muted); }}

  section {{ margin-bottom: 48px; }}
  .section-title {{ font-size: 18px; font-weight: 700; color: var(--text); border-left: 4px solid var(--accent); padding-left: 12px; margin-bottom: 20px; }}
  .section-desc {{ color: var(--muted); font-size: 13px; margin-bottom: 20px; margin-top: -12px; padding-left: 16px; }}

  /* ── Cards ── */
  .cards {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 24px; }}
  .card {{ background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 18px 20px; }}
  .card-label {{ font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); margin-bottom: 6px; }}
  .card-value {{ font-size: 28px; font-weight: 700; }}
  .card-sub {{ font-size: 12px; color: var(--muted); margin-top: 4px; }}
  .card.highlight {{ border-color: var(--accent); }}

  /* ── Tables ── */
  .table-wrap {{ overflow-x: auto; }}
  table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  thead tr {{ background: var(--surface2); }}
  th {{ padding: 10px 14px; text-align: left; font-weight: 600; color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; border-bottom: 1px solid var(--border); white-space: nowrap; }}
  td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); vertical-align: middle; }}
  tbody tr:hover {{ background: var(--surface2); }}
  .app-dot {{ display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 8px; vertical-align: middle; }}
  .rank {{ font-size: 11px; color: var(--muted); font-weight: 600; }}
  .badge {{ display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 600; }}
  .badge-green  {{ background: #16a34a22; color: #4ade80; }}
  .badge-red    {{ background: #dc262622; color: #f87171; }}
  .badge-yellow {{ background: #ca8a0422; color: #facc15; }}
  .badge-purple {{ background: #7c3aed22; color: #c4b5fd; }}
  .badge-blue   {{ background: #0369a122; color: #7dd3fc; }}

  /* ── Charts ── */
  .charts-grid {{ display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }}
  .charts-grid.single {{ grid-template-columns: 1fr; }}
  .chart-box {{ background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 20px; }}
  .chart-title {{ font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 16px; }}
  .chart-wrap {{ position: relative; height: 280px; }}
  .chart-wrap.tall {{ height: 340px; }}
  @media (max-width: 720px) {{ .charts-grid {{ grid-template-columns: 1fr; }} }}

  /* ── Insight boxes ── */
  .insight {{ background: var(--surface); border-left: 4px solid var(--accent); border-radius: 0 8px 8px 0; padding: 14px 18px; margin-bottom: 16px; }}
  .insight strong {{ color: var(--text); }}
  .insight.warn {{ border-color: #F59E0B; }}
  .insight.good {{ border-color: #22C55E; }}
  .insight.risk {{ border-color: #EF4444; }}

  /* ── Recommendations ── */
  .rec-grid {{ display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }}
  .rec {{ background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 18px; }}
  .rec-num {{ display: inline-block; width: 28px; height: 28px; border-radius: 50%; background: var(--accent); color: #0F172A; font-weight: 700; text-align: center; line-height: 28px; font-size: 13px; margin-bottom: 10px; }}
  .rec h4 {{ font-size: 13px; font-weight: 700; margin-bottom: 6px; }}
  .rec p {{ font-size: 12px; color: var(--muted); line-height: 1.6; }}
  @media (max-width: 720px) {{ .rec-grid {{ grid-template-columns: 1fr; }} }}

  /* ── Takeaways ── */
  .takeaway {{ display: flex; align-items: flex-start; gap: 14px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 16px 20px; margin-bottom: 12px; }}
  .takeaway-icon {{ font-size: 22px; flex-shrink: 0; margin-top: 2px; }}
  .takeaway h4 {{ font-size: 13px; font-weight: 700; margin-bottom: 4px; }}
  .takeaway p  {{ font-size: 12px; color: var(--muted); }}

  /* ── App legend pill ── */
  .legend {{ display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 20px; }}
  .legend-item {{ display: flex; align-items: center; gap: 6px; font-size: 12px; }}
  .legend-swatch {{ width: 12px; height: 12px; border-radius: 3px; }}

  /* ── Footer ── */
  footer {{ border-top: 1px solid var(--border); padding-top: 20px; margin-top: 40px; font-size: 11px; color: var(--muted); text-align: center; }}
</style>
</head>
<body>
<div class="wrapper">

<!-- ════════════════════════════════════════════════════════════════
     PAGE HEADER
════════════════════════════════════════════════════════════════ -->
<header class="page-header">
  <h1>Generative AI Competitive Landscape<br><span style="color:var(--accent)">User Sentiment &amp; Complaint Analysis — Q1 2026</span></h1>
  <p class="subtitle">A data-forward analysis of 50,000 mobile app reviews across ChatGPT, Microsoft Copilot, Google Gemini, Perplexity, and Claude</p>
  <div class="meta">
    <span class="meta-chip">Dataset: US Google Play Store · Early 2026</span>
    <span class="meta-chip">N = {d['total_reviews']:,} reviews</span>
    <span class="meta-chip">10,000 reviews per app</span>
    <span class="meta-chip">Audience: Product Strategy Team</span>
    <span class="meta-chip">Generated: April 23, 2026</span>
  </div>
</header>

<!-- ════════════════════════════════════════════════════════════════
     § 1  EXECUTIVE OVERVIEW
════════════════════════════════════════════════════════════════ -->
<section id="executive-overview">
  <h2 class="section-title">1 · Executive Overview</h2>

  <div class="cards">
    <div class="card highlight">
      <div class="card-label">Total Reviews Analysed</div>
      <div class="card-value" style="color:var(--accent)">{d['total_reviews']:,}</div>
      <div class="card-sub">5 apps · 10,000 each</div>
    </div>
    <div class="card">
      <div class="card-label">Leader — Star Rating</div>
      <div class="card-value" style="color:var(--copilot)">{d['avg_star'][best_star_app]:.2f}★</div>
      <div class="card-sub">{best_star_app}</div>
    </div>
    <div class="card">
      <div class="card-label">Leader — Sentiment Polarity</div>
      <div class="card-value" style="color:var(--copilot)">{d['avg_polarity'][best_pol_app]:.3f}</div>
      <div class="card-sub">{best_pol_app}</div>
    </div>
    <div class="card">
      <div class="card-label">Laggard — Star Rating</div>
      <div class="card-value" style="color:#EF4444">{d['avg_star'][worst_star_app]:.2f}★</div>
      <div class="card-sub">{worst_star_app}</div>
    </div>
    <div class="card">
      <div class="card-label">Highest Mismatch Rate</div>
      <div class="card-value" style="color:#F59E0B">{d['mismatch_rate'][most_mismatch]:.1f}%</div>
      <div class="card-sub">{most_mismatch}</div>
    </div>
  </div>

  <h3 style="font-size:14px;font-weight:700;color:var(--muted);margin-bottom:14px;text-transform:uppercase;letter-spacing:0.06em;">Top 3 Strategic Takeaways</h3>

  <div class="takeaway">
    <div class="takeaway-icon">🏆</div>
    <div>
      <h4>Microsoft Copilot leads on both objective metrics — but its advantage is narrowing.</h4>
      <p>Copilot scores {d['avg_star']['Microsoft Copilot']:.2f}★ average (vs. sector mean {sum(d['avg_star'].values())/5:.2f}★) and a VADER polarity of {d['avg_polarity']['Microsoft Copilot']:.3f} — 0.12 points above the next competitor. Its 1-star rate is a sector-low 11.3% and 5-star rate is a sector-high 68.2%. However, it also attracts the most engagement per review (avg {d['avg_thumbs']['Microsoft Copilot']:.1f} thumbs-ups), suggesting reviewers are unusually vocal — monitor for sentiment shifts as the product matures.</p>
    </div>
  </div>

  <div class="takeaway">
    <div class="takeaway-icon">⚠️</div>
