#!/usr/bin/env python3
"""Generate the HTML competitive analysis report from pre-computed KPIs."""

import json
import math

with open('/app/kpi_results.json') as f:
    d = json.load(f)

APPS = d['apps_order']
APP_COLORS = {
    'ChatGPT':           '#10A37F',
    'Microsoft Copilot': '#0078D4',
    'Google Gemini':     '#DB4437',
    'Perplexity':        '#5C6BC0',
    'Claude':            '#D4873B',
}
THEME_COLORS = {
    'General':               '#94A3B8',
    'Pricing/Subscription':  '#F59E0B',
    'Bugs/Performance':      '#EF4444',
    'Accuracy/Logic Issues': '#8B5CF6',
}

def pct_bar(value, max_val=100, color='#10A37F', height=18, width=220):
    """Return an SVG horizontal bar."""
    fill = max(0, min(value / max_val, 1)) * width
    return (
        f'<svg width="{width}" height="{height}" style="vertical-align:middle">'
        f'<rect width="{width}" height="{height}" rx="3" fill="#E2E8F0"/>'
        f'<rect width="{fill:.1f}" height="{height}" rx="3" fill="{color}"/>'
        f'</svg>'
    )

def stars_svg(rating, color='#F59E0B'):
    """Return SVG stars for a rating."""
    full = int(rating)
    frac = rating - full
    svgs = []
    cx = 0
    for i in range(5):
        if i < full:
            svgs.append(f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="{color}"/>')
        elif i == full and frac >= 0.3:
            # half star clip
            svgs.append(
                f'<defs><clipPath id="h{i}"><rect x="{cx}" y="0" width="10" height="20"/></clipPath></defs>'
                f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="#E2E8F0"/>'
                f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="{color}" clip-path="url(#h{i})"/>'
            )
        else:
            svgs.append(f'<polygon points="{cx+10},2 {cx+12},8 {cx+18},8 {cx+13},12 {cx+15},18 {cx+10},14 {cx+5},18 {cx+7},12 {cx+2},8 {cx+8},8" fill="#E2E8F0"/>')
        cx += 22
    return f'<svg width="{cx}" height="20" style="vertical-align:middle">{"".join(svgs)}</svg>'

# ─── Build chart data for Chart.js ─────────────────────────────────────────────
app_labels = json.dumps(APPS)
bg_colors   = json.dumps([APP_COLORS[a] for a in APPS])
star_vals   = json.dumps([round(d['avg_star'][a], 3) for a in APPS])
pol_vals    = json.dumps([round(d['avg_polarity'][a], 4) for a in APPS])
mis_vals    = json.dumps([round(d['mismatch_rate'][a], 2) for a in APPS])
thumb_vals  = json.dumps([round(d['avg_thumbs'][a], 3) for a in APPS])
words_vals  = json.dumps([round(d['avg_words'][a], 1) for a in APPS])

THEMES = ['General', 'Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']
theme_datasets = []
for theme in THEMES:
    vals = [round(d['theme_pct'].get(a, {}).get(theme, 0), 2) for a in APPS]
    theme_datasets.append({
        'label': theme,
        'data': vals,
        'backgroundColor': THEME_COLORS[theme],
    })
theme_datasets_json = json.dumps(theme_datasets)

# Star distribution stacked bar
STAR_COLORS = {1: '#EF4444', 2: '#F97316', 3: '#EAB308', 4: '#84CC16', 5: '#22C55E'}
star_datasets = []
for star in [1, 2, 3, 4, 5]:
    vals = [round(d['star_dist_pct'].get(a, {}).get(star, 0), 2) for a in APPS]
    star_datasets.append({'label': f'{star}★', 'data': vals, 'backgroundColor': STAR_COLORS[star]})
star_datasets_json = json.dumps(star_datasets)

# Polarity buckets grouped bar
POL_BUCKETS = ['Very Neg', 'Neg', 'Neutral', 'Pos', 'Very Pos']
POL_COLORS  = ['#EF4444', '#F97316', '#94A3B8', '#84CC16', '#22C55E']
pol_datasets = []
for bucket, color in zip(POL_BUCKETS, POL_COLORS):
    vals = [round(d['pol_dist_pct'].get(a, {}).get(bucket, 0), 2) for a in APPS]
    pol_datasets.append({'label': bucket, 'data': vals, 'backgroundColor': color})
pol_datasets_json = json.dumps(pol_datasets)

# Theme thumbs-up
theme_thumb_labels = json.dumps(list(d['theme_thumbs'].keys()))
theme_thumb_vals   = json.dumps([round(v, 3) for v in d['theme_thumbs'].values()])
theme_thumb_colors = json.dumps([THEME_COLORS.get(t, '#94A3B8') for t in d['theme_thumbs'].keys()])

# Words by star
words_by_star_labels = json.dumps([f'{s}★' for s in d['words_by_star'].keys()])
words_by_star_vals   = json.dumps([round(v, 1) for v in d['words_by_star'].values()])
words_by_star_colors = json.dumps([STAR_COLORS[s] for s in [int(k) for k in d['words_by_star'].keys()]])

# ─── KPI cards data ─────────────────────────────────────────────────────────────
best_star_app = max(APPS, key=lambda a: d['avg_star'][a])
worst_star_app = min(APPS, key=lambda a: d['avg_star'][a])
best_pol_app  = max(APPS, key=lambda a: d['avg_polarity'][a])
most_pricing  = max(APPS, key=lambda a: d['theme_pct'].get(a, {}).get('Pricing/Subscription', 0))
most_bugs     = max(APPS, key=lambda a: d['theme_pct'].get(a, {}).get('Bugs/Performance', 0))
most_accuracy = max(APPS, key=lambda a: d['theme_pct'].get(a, {}).get('Accuracy/Logic Issues', 0))
most_mismatch = max(APPS, key=lambda a: d['mismatch_rate'][a])
least_mismatch = min(APPS, key=lambda a: d['mismatch_rate'][a])
most_thumbs   = max(APPS, key=lambda a: d['avg_thumbs'][a])

# ─── HTML Template ──────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Generative AI Competitive Landscape Q1 2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.2/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0F172A;
    --surface: #1E293B;
    --surface2: #273447;
    --border: #334155;
    --text: #F1F5F9;
