    --chatgpt: {APP_COLORS['ChatGPT']};
    --copilot: {APP_COLORS['Microsoft Copilot']};
    --gemini:  {APP_COLORS['Google Gemini']};
    --perplexity: {APP_COLORS['Perplexity']};
    --claude:  {APP_COLORS['Claude']};
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ background: var(--bg); color: var(--text); font-family: 'Segoe UI', system-ui, sans-serif; font-size: 14px; line-height: 1.6; }}
  a {{ color: var(--accent); }}

  /* ── Layout ── */
  .wrapper {{ max-width: 1200px; margin: 0 auto; padding: 32px 24px; }}
  .page-header {{ border-bottom: 2px solid var(--border); padding-bottom: 24px; margin-bottom: 36px; }}
  .page-header h1 {{ font-size: 26px; font-weight: 700; color: var(--text); line-height: 1.3; }}
  .page-header .subtitle {{ color: var(--muted); font-size: 13px; margin-top: 6px; }}
  .page-header .meta {{ display: flex; gap: 24px; margin-top: 12px; flex-wrap: wrap; }}
  .meta-chip {{ background: var(--surface); border: 1px solid var(--border); border-radius: 20px; padding: 4px 14px; font-size: 12px; color: var(--muted); }}

  section {{ margin-bottom: 48px; }}
  .section-title {{ font-size: 18px; font-weight: 700; color: var(--text); border-left: 4px solid var(--accent); padding-left: 12px; margin-bottom: 20px; }}
  .section-desc {{ color: var(--muted); font-size: 13px; margin-bottom: 20px; margin-top: -12px; padding-left: 16px; }}

  /* ── Cards ── */
  .cards {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 24px; }}
  .card {{ background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 18px 20px; }}
  .card-label {{ font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); margin-bottom: 6px; }}
  .card-value {{ font-size: 28px; font-weight: 700; }}
  .card-sub {{ font-size: 12px; color: var(--muted); margin-top: 4px; }}
  .card.highlight {{ border-color: var(--accent); }}

  /* ── Tables ── */
  .table-wrap {{ overflow-x: auto; }}
  table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  thead tr {{ background: var(--surface2); }}
  th {{ padding: 10px 14px; text-align: left; font-weight: 600; color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; border-bottom: 1px solid var(--border); white-space: nowrap; }}
  td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); vertical-align: middle; }}
  tbody tr:hover {{ background: var(--surface2); }}
  .app-dot {{ display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 8px; vertical-align: middle; }}
  .rank {{ font-size: 11px; color: var(--muted); font-weight: 600; }}
  .badge {{ display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 600; }}
  .badge-green  {{ background: #16a34a22; color: #4ade80; }}
  .badge-red    {{ background: #dc262622; color: #f87171; }}
  .badge-yellow {{ background: #ca8a0422; color: #facc15; }}
  .badge-purple {{ background: #7c3aed22; color: #c4b5fd; }}
  .badge-blue   {{ background: #0369a122; color: #7dd3fc; }}

  /* ── Charts ── */
  .charts-grid {{ display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }}
  .charts-grid.single {{ grid-template-columns: 1fr; }}
  .chart-box {{ background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 20px; }}
  .chart-title {{ font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 16px; }}
  .chart-wrap {{ position: relative; height: 280px; }}
  .chart-wrap.tall {{ height: 340px; }}
  @media (max-width: 720px) {{ .charts-grid {{ grid-template-columns: 1fr; }} }}

  /* ── Insight boxes ── */
  .insight {{ background: var(--surface); border-left: 4px solid var(--accent); border-radius: 0 8px 8px 0; padding: 14px 18px; margin-bottom: 16px; }}
  .insight strong {{ color: var(--text); }}
  .insight.warn {{ border-color: #F59E0B; }}
  .insight.good {{ border-color: #22C55E; }}
  .insight.risk {{ border-color: #EF4444; }}

  /* ── Recommendations ── */
  .rec-grid {{ display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }}
  .rec {{ background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 18px; }}
  .rec-num {{ display: inline-block; width: 28px; height: 28px; border-radius: 50%; background: var(--accent); color: #0F172A; font-weight: 700; text-align: center; line-height: 28px; font-size: 13px; margin-bottom: 10px; }}
  .rec h4 {{ font-size: 13px; font-weight: 700; margin-bottom: 6px; }}
  .rec p {{ font-size: 12px; color: var(--muted); line-height: 1.6; }}
  @media (max-width: 720px) {{ .rec-grid {{ grid-template-columns: 1fr; }} }}

  /* ── Takeaways ── */
  .takeaway {{ display: flex; align-items: flex-start; gap: 14px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 16px 20px; margin-bottom: 12px; }}
  .takeaway-icon {{ font-size: 22px; flex-shrink: 0; margin-top: 2px; }}
  .takeaway h4 {{ font-size: 13px; font-weight: 700; margin-bottom: 4px; }}
  .takeaway p  {{ font-size: 12px; color: var(--muted); }}

  /* ── App legend pill ── */
  .legend {{ display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 20px; }}
  .legend-item {{ display: flex; align-items: center; gap: 6px; font-size: 12px; }}
  .legend-swatch {{ width: 12px; height: 12px; border-radius: 3px; }}

  /* ── Footer ── */
  footer {{ border-top: 1px solid var(--border); padding-top: 20px; margin-top: 40px; font-size: 11px; color: var(--muted); text-align: center; }}
</style>
</head>
<body>
<div class="wrapper">

<!-- ════════════════════════════════════════════════════════════════
     PAGE HEADER
════════════════════════════════════════════════════════════════ -->
<header class="page-header">
  <h1>Generative AI Competitive Landscape<br><span style="color:var(--accent)">User Sentiment &amp; Complaint Analysis — Q1 2026</span></h1>
  <p class="subtitle">A data-forward analysis of 50,000 mobile app reviews across ChatGPT, Microsoft Copilot, Google Gemini, Perplexity, and Claude</p>
  <div class="meta">
    <span class="meta-chip">Dataset: US Google Play Store · Early 2026</span>
    <span class="meta-chip">N = {d['total_reviews']:,} reviews</span>
    <span class="meta-chip">10,000 reviews per app</span>
    <span class="meta-chip">Audience: Product Strategy Team</span>
    <span class="meta-chip">Generated: April 23, 2026</span>
  </div>
</header>

<!-- ════════════════════════════════════════════════════════════════
     § 1  EXECUTIVE OVERVIEW
════════════════════════════════════════════════════════════════ -->
<section id="executive-overview">
  <h2 class="section-title">1 · Executive Overview</h2>

  <div class="cards">
    <div class="card highlight">
      <div class="card-label">Total Reviews Analysed</div>
      <div class="card-value" style="color:var(--accent)">{d['total_reviews']:,}</div>
      <div class="card-sub">5 apps · 10,000 each</div>
    </div>
    <div class="card">
      <div class="card-label">Leader — Star Rating</div>
      <div class="card-value" style="color:var(--copilot)">{d['avg_star'][best_star_app]:.2f}★</div>
      <div class="card-sub">{best_star_app}</div>
    </div>
    <div class="card">
      <div class="card-label">Leader — Sentiment Polarity</div>
      <div class="card-value" style="color:var(--copilot)">{d['avg_polarity'][best_pol_app]:.3f}</div>
      <div class="card-sub">{best_pol_app}</div>
    </div>
    <div class="card">
      <div class="card-label">Laggard — Star Rating</div>
      <div class="card-value" style="color:#EF4444">{d['avg_star'][worst_star_app]:.2f}★</div>
      <div class="card-sub">{worst_star_app}</div>
    </div>
    <div class="card">
      <div class="card-label">Highest Mismatch Rate</div>
      <div class="card-value" style="color:#F59E0B">{d['mismatch_rate'][most_mismatch]:.1f}%</div>
      <div class="card-sub">{most_mismatch}</div>
    </div>
  </div>

  <h3 style="font-size:14px;font-weight:700;color:var(--muted);margin-bottom:14px;text-transform:uppercase;letter-spacing:0.06em;">Top 3 Strategic Takeaways</h3>

  <div class="takeaway">
    <div class="takeaway-icon">🏆</div>
    <div>
      <h4>Microsoft Copilot leads on both objective metrics — but its advantage is narrowing.</h4>
      <p>Copilot scores {d['avg_star']['Microsoft Copilot']:.2f}★ average (vs. sector mean {sum(d['avg_star'].values())/5:.2f}★) and a VADER polarity of {d['avg_polarity']['Microsoft Copilot']:.3f} — 0.12 points above the next competitor. Its 1-star rate is a sector-low 11.3% and 5-star rate is a sector-high 68.2%. However, it also attracts the most engagement per review (avg {d['avg_thumbs']['Microsoft Copilot']:.1f} thumbs-ups), suggesting reviewers are unusually vocal — monitor for sentiment shifts as the product matures.</p>
    </div>
  </div>

  <div class="takeaway">
    <div class="takeaway-icon">⚠️</div>
    <div>
      <h4>Perplexity and Claude carry the sector's highest pricing complaint rates — a direct retention risk.</h4>
      <p>Claude leads all apps in Pricing/Subscription complaints at {d['theme_pct']['Claude']['Pricing/Subscription']:.1f}% of reviews; Perplexity follows at {d['theme_pct']['Perplexity']['Pricing/Subscription']:.1f}%. Both are roughly 3–5× the rate of Copilot ({d['theme_pct']['Microsoft Copilot']['Pricing/Subscription']:.1f}%). Pricing complaints carry a high engagement multiplier ({d['theme_thumbs']['Pricing/Subscription']:.1f} avg thumbs-ups vs. {d['theme_thumbs']['General']:.1f} for General), meaning discontented users about paywalls amplify disproportionately across the community.</p>
    </div>
  </div>

  <div class="takeaway">
    <div class="takeaway-icon">🔍</div>
    <div>
      <h4>Sentiment-rating mismatch rates expose hidden dissatisfaction that star averages miss.</h4>
      <p>Claude ({d['mismatch_rate']['Claude']:.1f}%) and Perplexity ({d['mismatch_rate']['Perplexity']:.1f}%) have the highest divergence rates — meaning ~1 in 7 reviews contains conflicting signals (sarcastic praise or frustrated 5-stars). Copilot has the lowest mismatch at {d['mismatch_rate']['Microsoft Copilot']:.1f}%. Teams relying solely on star ratings are likely under-counting dissatisfaction at Claude and over-counting satisfaction for the sector leader.</p>
    </div>
  </div>
</section>

<!-- ════════════════════════════════════════════════════════════════
     § 2  CROSS-APP SENTIMENT COMPARISON
════════════════════════════════════════════════════════════════ -->
<section id="app-sentiment-comparison">
  <h2 class="section-title">2 · Cross-App Sentiment Comparison</h2>
  <p class="section-desc">Average star ratings, VADER sentiment polarity, and rating distributions across all five applications.</p>

  <div class="legend">
    {"".join(f'<span class="legend-item"><span class="legend-swatch" style="background:{APP_COLORS[a]}"></span>{a}</span>' for a in APPS)}
  </div>

  <!-- KPI Table -->
  <div class="table-wrap" style="margin-bottom:24px">
  <table>
    <thead>
      <tr>
        <th>Rank</th><th>Application</th>
        <th>Avg Star Rating</th><th>Stars</th>
        <th>Mean Sentiment Polarity</th>
        <th>5★ Share</th><th>1★ Share</th>
        <th>Avg Thumbs-Up</th>
      </tr>
    </thead>
    <tbody>
"""
sorted_apps = sorted(APPS, key=lambda a: d['avg_star'][a], reverse=True)
for rank, app in enumerate(sorted_apps, 1):
    star = d['avg_star'][app]
    pol  = d['avg_polarity'][app]
    share5 = d['star_dist_pct'][app].get(5, 0)
    share1 = d['star_dist_pct'][app].get(1, 0)
    thumbs = d['avg_thumbs'][app]
    pol_badge = 'badge-green' if pol >= 0.4 else 'badge-yellow' if pol >= 0.3 else 'badge-red'
    html += f"""
      <tr>
        <td class="rank">#{rank}</td>
        <td><span class="app-dot" style="background:{APP_COLORS[app]}"></span><strong>{app}</strong></td>
        <td><strong>{star:.3f}</strong></td>
        <td>{pct_bar(star, max_val=5, color=APP_COLORS[app], height=14, width=160)}</td>
        <td><span class="badge {pol_badge}">{pol:+.4f}</span></td>
        <td>{share5:.1f}%</td>
        <td>{share1:.1f}%</td>
        <td>{thumbs:.3f}</td>
      </tr>"""

html += """
    </tbody>
  </table>
  </div>

  <div class="charts-grid">
    <div class="chart-box">
      <div class="chart-title">Average Star Rating by App</div>
      <div class="chart-wrap"><canvas id="chartStarBar"></canvas></div>
    </div>
    <div class="chart-box">
      <div class="chart-title">Mean VADER Sentiment Polarity by App</div>
      <div class="chart-wrap"><canvas id="chartPolBar"></canvas></div>
    </div>
    <div class="chart-box">
      <div class="chart-title">Star Rating Distribution (%) — Stacked</div>
      <div class="chart-wrap tall"><canvas id="chartStarStack"></canvas></div>
    </div>
    <div class="chart-box">
      <div class="chart-title">Sentiment Polarity Bucket Distribution (%)</div>
      <div class="chart-wrap tall"><canvas id="chartPolBucket"></canvas></div>
    </div>
  </div>

  <div class="insight good" style="margin-top:20px">
    <strong>Key finding:</strong> Microsoft Copilot's star advantage is reinforced by its VADER score (+{d['avg_polarity']['Microsoft Copilot']:.3f}), the highest in the category. Google Gemini and Perplexity trail on both dimensions. Notably, Google Gemini has the highest 1-star share ({d['star_dist_pct']['Google Gemini'].get(1,0):.1f}%) and lowest 5-star share among the major players, suggesting deeper structural dissatisfaction.
  </div>
</section>

<!-- ════════════════════════════════════════════════════════════════
     § 3  THEMATIC COMPLAINT ANALYSIS
════════════════════════════════════════════════════════════════ -->
<section id="thematic-complaint-analysis">
  <h2 class="section-title">3 · Thematic Complaint Analysis</h2>
  <p class="section-desc">Review_Theme breakdown (Pricing/Subscription, Bugs/Performance, Accuracy/Logic Issues, General) per app. Themes are regex-derived; a single review carries one tag.</p>

  <div class="cards">
    <div class="card">
      <div class="card-label">Highest Pricing Complaints</div>
      <div class="card-value" style="color:#F59E0B">{d['theme_pct'][most_pricing]['Pricing/Subscription']:.1f}%</div>
      <div class="card-sub">{most_pricing}</div>
    </div>
    <div class="card">
      <div class="card-label">Highest Bug Complaints</div>
      <div class="card-value" style="color:#EF4444">{d['theme_pct'][most_bugs].get('Bugs/Performance',0):.1f}%</div>
      <div class="card-sub">{most_bugs}</div>
    </div>
    <div class="card">
      <div class="card-label">Highest Accuracy Complaints</div>
      <div class="card-value" style="color:#8B5CF6">{d['theme_pct'][most_accuracy].get('Accuracy/Logic Issues',0):.1f}%</div>
      <div class="card-sub">{most_accuracy}</div>
    </div>
    <div class="card">
      <div class="card-label">Bugs Avg Thumbs-Up</div>
      <div class="card-value" style="color:#EF4444">{d['theme_thumbs']['Bugs/Performance']:.2f}</div>
      <div class="card-sub">Highest community resonance</div>
    </div>
  </div>

  <!-- Detailed theme table -->
  <div class="table-wrap" style="margin-bottom:24px">
  <table>
    <thead>
      <tr>
        <th>Application</th>
        <th>General</th>
        <th><span style="color:#F59E0B">Pricing/Subscription</span></th>
        <th><span style="color:#EF4444">Bugs/Performance</span></th>
        <th><span style="color:#8B5CF6">Accuracy/Logic Issues</span></th>
        <th>Non-General Total</th>
      </tr>
    </thead>
    <tbody>
"""
for app in APPS:
    t = d['theme_pct'].get(app, {})
    gen   = t.get('General', 0)
    price = t.get('Pricing/Subscription', 0)
    bugs  = t.get('Bugs/Performance', 0)
    acc   = t.get('Accuracy/Logic Issues', 0)
    total_complaint = price + bugs + acc
    html += f"""
      <tr>
        <td><span class="app-dot" style="background:{APP_COLORS[app]}"></span><strong>{app}</strong></td>
        <td>{gen:.2f}%</td>
        <td>
          {pct_bar(price, max_val=10, color='#F59E0B', height=12, width=130)}
          <span style="margin-left:6px">{price:.2f}%</span>
        </td>
        <td>
          {pct_bar(bugs, max_val=10, color='#EF4444', height=12, width=130)}
          <span style="margin-left:6px">{bugs:.2f}%</span>
        </td>
        <td>
          {pct_bar(acc, max_val=10, color='#8B5CF6', height=12, width=130)}
          <span style="margin-left:6px">{acc:.2f}%</span>
        </td>
        <td><strong>{total_complaint:.2f}%</strong></td>
      </tr>"""

html += f"""
    </tbody>
  </table>
  </div>

  <div class="charts-grid">
    <div class="chart-box">
      <div class="chart-title">Theme Distribution per App (Grouped %)</div>
      <div class="chart-wrap tall"><canvas id="chartThemeBar"></canvas></div>
    </div>
    <div class="chart-box">
      <div class="chart-title">Avg Thumbs-Up per Theme (Community Resonance)</div>
      <div class="chart-wrap"><canvas id="chartThemeThumbs"></canvas></div>
    </div>
  </div>

  <div class="insight warn" style="margin-top:20px">
    <strong>Pricing Alert — Claude &amp; Perplexity:</strong> Claude's {d['theme_pct']['Claude']['Pricing/Subscription']:.1f}% pricing complaint rate and Perplexity's {d['theme_pct']['Perplexity']['Pricing/Subscription']:.1f}% are the two highest in the field — over 3× Copilot's {d['theme_pct']['Microsoft Copilot']['Pricing/Subscription']:.1f}%. Pricing complaints earn {d['theme_thumbs']['Pricing/Subscription']:.1f} avg thumbs-ups, which means each complaint amplifies to a wider audience of concerned users.
  </div>
  <div class="insight risk" style="margin-top:12px">
    <strong>Bug Resonance is Sector-Wide:</strong> Bugs/Performance reviews earn the highest community endorsement across all themes ({d['theme_thumbs']['Bugs/Performance']:.1f} avg thumbs-ups). This means bug reports have outsized influence on potential users reading reviews. {most_bugs} leads with {d['theme_pct'][most_bugs].get('Bugs/Performance',0):.1f}% bug complaints.
  </div>
</section>

<!-- ════════════════════════════════════════════════════════════════
     § 4  SENTIMENT-RATING DIVERGENCE
════════════════════════════════════════════════════════════════ -->
<section id="sentiment-rating-divergence">
  <h2 class="section-title">4 · Sentiment-Rating Divergence &amp; Sarcasm Detection</h2>
  <p class="section-desc">Reviews where star ratings and VADER polarity conflict: high-star reviews with negative polarity (&lt;−0.05), or low-star reviews with positive polarity (&gt;+0.05).</p>

  <div class="cards">
"""
for app in APPS:
    rate = d['mismatch_rate'][app]
    color = '#EF4444' if rate > 13 else '#F59E0B' if rate > 10 else '#22C55E'
    html += f"""
    <div class="card">
      <div class="card-label">{app}</div>
      <div class="card-value" style="color:{color}">{rate:.2f}%</div>
      <div class="card-sub">mismatch rate</div>
    </div>"""

html += f"""
  </div>

  <div class="charts-grid" style="margin-top:20px">
    <div class="chart-box">
      <div class="chart-title">Sentiment-Rating Mismatch Rate by App (%)</div>
      <div class="chart-wrap"><canvas id="chartMismatch"></canvas></div>
    </div>
    <div class="chart-box" style="padding:20px">
      <div class="chart-title">Interpretation Guide</div>
      <div style="margin-top:10px">
        <div class="insight good" style="margin-bottom:10px">
          <strong>Low mismatch (&lt;10%):</strong> Star ratings reliably predict review sentiment. {least_mismatch} is the most "honest" app at {d['mismatch_rate'][least_mismatch]:.1f}% — its star average is a trustworthy signal.
        </div>
        <div class="insight warn" style="margin-bottom:10px">
          <strong>Medium mismatch (10–13%):</strong> ChatGPT ({d['mismatch_rate']['ChatGPT']:.1f}%) and Google Gemini ({d['mismatch_rate']['Google Gemini']:.1f}%) show moderate divergence. Star ratings capture most sentiment but miss a meaningful slice.
        </div>
        <div class="insight risk" style="margin-bottom:10px">
          <strong>High mismatch (&gt;13%):</strong> Claude ({d['mismatch_rate']['Claude']:.1f}%) and Perplexity ({d['mismatch_rate']['Perplexity']:.1f}%) have the most conflicted reviewer pools. A 4–5 star review may harbour genuine frustration (e.g., "great product <em>but</em> the paywall is criminal"), inflating perceived satisfaction.
        </div>
        <div style="font-size:12px;color:var(--muted);margin-top:16px;line-height:1.7">
          <strong style="color:var(--text)">Methodology:</strong> Mismatch is defined as:<br>
          &bull; Star ≥ 4 AND Polarity &lt; −0.05 (high-star, negative text)<br>
          &bull; Star ≤ 2 AND Polarity &gt; +0.05 (low-star, positive text)<br>
          VADER scores of 0.0 (Unicode-styled text) are treated as neutral and excluded from mismatch classification to avoid false positives.
        </div>
      </div>
    </div>
  </div>

  <div class="insight warn" style="margin-top:20px">
    <strong>Strategic implication:</strong> Claude's {d['mismatch_rate']['Claude']:.1f}% mismatch rate means its {d['avg_star']['Claude']:.2f}★ average likely overstates user satisfaction. When controlling for sarcasm and qualified praise, Claude's effective satisfaction score is closer to its VADER polarity ({d['avg_polarity']['Claude']:.3f}) — still positive, but the gap from Copilot ({d['avg_polarity']['Microsoft Copilot']:.3f} polarity) is larger than star ratings suggest.
  </div>
</section>

<!-- ════════════════════════════════════════════════════════════════
     § 5  REVIEW DEPTH & EMOTIONAL INTENSITY
════════════════════════════════════════════════════════════════ -->
<section id="review-depth-emotion">
  <h2 class="section-title">5 · Review Depth &amp; Emotional Intensity</h2>
  <p class="section-desc">Relationship between review length (Word_Count), sentiment polarity, star rating, and community engagement (Thumbs_Up_Count).</p>

  <div class="cards">
"""
for app in APPS:
    wc = d['avg_words'][app]
    html += f"""
    <div class="card">
      <div class="card-label">{app}</div>
      <div class="card-value" style="color:{APP_COLORS[app]}">{wc:.1f}</div>
      <div class="card-sub">avg words / review</div>
    </div>"""

html += f"""
  </div>

  <div class="charts-grid" style="margin-top:20px">
    <div class="chart-box">
      <div class="chart-title">Average Word Count by App</div>
      <div class="chart-wrap"><canvas id="chartWords"></canvas></div>
    </div>
    <div class="chart-box">
      <div class="chart-title">Avg Word Count by Star Rating — Sector Wide</div>
      <div class="chart-wrap"><canvas id="chartWordsByStar"></canvas></div>
    </div>
  </div>

  <!-- Correlation table -->
  <div class="table-wrap" style="margin-top:24px;margin-bottom:20px">
  <table>
    <thead>
      <tr>
        <th>Application</th>
        <th>Avg Words / Review</th>
        <th>Word-Count × Polarity Corr.</th>
        <th>Word-Count × Star Rating Corr.</th>
        <th>Interpretation</th>
      </tr>
    </thead>
    <tbody>
"""
for app in APPS:
    wc   = d['avg_words'][app]
    wpc  = d['wc_pol_corr'][app]
    wsc  = d['wc_star_corr'][app]
    interp = "Longer reviews tend negative" if wpc < -0.04 else "Weak length-sentiment link"
    html += f"""
      <tr>
