function mkBar(id, labels, data, colors, opts={{}}) {{
  const ctx = document.getElementById(id);
  if (!ctx) return;
  new Chart(ctx, {{
    type: 'bar',
    data: {{ labels, datasets: [{{ data, backgroundColor: colors, borderRadius: 5, borderSkipped: false }}] }},
    options: {{
      responsive: true, maintainAspectRatio: false,
      plugins: {{ legend: {{ display: false }}, tooltip: {{ callbacks: {{ label: c => ' ' + c.parsed.y.toFixed(3) }} }} }},
      scales: {{ y: {{ beginAtZero: true, grid: {{ color: '#334155' }} }}, x: {{ grid: {{ display: false }} }} }},
      ...opts
    }}
  }});
}}

function mkGrouped(id, labels, datasets, yLabel='', stacked=false) {{
  const ctx = document.getElementById(id);
  if (!ctx) return;
  new Chart(ctx, {{
    type: 'bar',
    data: {{ labels, datasets: datasets.map(ds => ({{ ...ds, borderRadius: stacked ? 0 : 3 }})) }},
    options: {{
      responsive: true, maintainAspectRatio: false,
      plugins: {{ legend: {{ position: 'bottom', labels: {{ boxWidth: 12, padding: 10, font: {{ size: 11 }} }} }} }},
      scales: {{
        y: {{ beginAtZero: true, stacked, grid: {{ color: '#334155' }}, title: {{ display: !!yLabel, text: yLabel }} }},
        x: {{ stacked, grid: {{ display: false }} }}
      }}
    }}
  }});
}}

